-- PT118-S3-Q15. Batch 13.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch13$PT118-S3-Q15$batch13$ AND q.stimulus=$batch13$Psychologist: Doctors should never prescribe sedatives for people with insomnia. Most cases of insomnia that psychologists treat are known to be caused by psychological stress. This suggests that insomniacs do not need drugs that alter their biochemistry, but rather need psychotherapy to help them alleviate the stress causing their insomnia.$batch13$ AND q.prompt=$batch13$Each of the following describes a flaw in the psychologist's reasoning EXCEPT:$batch13$ AND q.correct_choice=$batch13$A$batch13$) THEN RAISE EXCEPTION 'Question changed: PT118-S3-Q15'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch13$PT118-S3-Q15$batch13$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT118-S3-Q15'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch13$PT118-S3-Q15$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch13$Conclusion$batch13$, $batch13$Doctors should never prescribe sedatives for insomnia. Insomniacs need psychotherapy to relieve their stress, not drugs.$batch13$), (1, $batch13$Evidence$batch13$, $batch13$Most cases of insomnia that psychologists treat are caused by stress.$batch13$), (2, $batch13$Evaluate$batch13$, $batch13$This is an EXCEPT question. The argument has many holes: "most" isn't all, psychologists' patients may not be typical, therapy may not work for everyone, and sedatives might help too. Four choices name a real flaw. The answer describes something the argument never assumes.$batch13$), (3, $batch13$Goal$batch13$, $batch13$Find the choice that isn't a flaw in this reasoning.$batch13$)) v(position,label,body) WHERE q.qid=$batch13$PT118-S3-Q15$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch13$A$batch13$, $batch13$The argument assumes stress causes insomnia, not that insomnia makes people worse at coping with stress. This reverses the direction, so it isn't something the argument presumes.$batch13$), ($batch13$B$batch13$, $batch13$"Most" leaves cases not caused by stress. Sedatives might be the only treatment for those, yet the conclusion says "never".$batch13$), ($batch13$C$batch13$, $batch13$The argument assumes psychotherapy works. For some people it may not.$batch13$), ($batch13$D$batch13$, $batch13$Sedatives could help people manage stress, which would serve the same goal.$batch13$), ($batch13$E$batch13$, $batch13$This is the most popular trap. Psychologists' patients may not be typical of insomniacs, so the sample may be unrepresentative. It's a real flaw.$batch13$)) v(letter,body) WHERE q.qid=$batch13$PT118-S3-Q15$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
